// Validator for the JSON Schema subset emitted by our Pydantic save model.
// Keeping the schema generated by the backend prevents divergent field limits.
const schema=require('../../dist/save-schema.js');
function validateSchema(value,rule=schema,path='save'){
  if(rule.$ref)return validateSchema(value,schema.$defs[rule.$ref.split('/').pop()],path);
  if(rule.anyOf){for(const option of rule.anyOf){try{validateSchema(value,option,path);return;}catch(_){}}throw Error(path+' 类型不正确');}
  const fail=reason=>{throw Error(path+' '+reason);};
  if(rule.const!==undefined&&value!==rule.const)fail('版本不支持');
  if(rule.enum&&!rule.enum.includes(value))fail('选项无效');
  if(rule.type==='null'){if(value!==null)fail('应为空');return;}
  if(rule.type==='object'){
    if(!value||typeof value!=='object'||Array.isArray(value))fail('应为对象');
    for(const key of rule.required||[])if(!Object.prototype.hasOwnProperty.call(value,key))fail('缺少 '+key);
    if(rule.maxProperties&&Object.keys(value).length>rule.maxProperties)fail('字段过多');
    for(const key of Object.keys(value)){
      if(['__proto__','constructor','prototype'].includes(key))fail('字段无效');
      const child=Object.prototype.hasOwnProperty.call(rule.properties||{},key)?rule.properties[key]:rule.additionalProperties;
      if(child===false)fail('未知字段 '+key);
      if(child&&child!==true)validateSchema(value[key],child,path+'.'+key);
    }
  }else if(rule.type==='array'){
    if(!Array.isArray(value))fail('应为列表');
    if(rule.maxItems&&value.length>rule.maxItems)fail('列表过长');
    value.forEach((item,i)=>validateSchema(item,rule.items,path+'['+i+']'));
  }else if(rule.type==='string'){
    if(typeof value!=='string')fail('应为文本');
    if(rule.maxLength&&value.length>rule.maxLength)fail('文本过长');
    if(rule.pattern&&!new RegExp(rule.pattern).test(value))fail('格式无效');
  }else if(rule.type==='boolean'){
    if(typeof value!=='boolean')fail('应为布尔值');
  }else if(rule.type==='integer'||rule.type==='number'){
    if(typeof value!=='number'||!Number.isFinite(value)||rule.type==='integer'&&!Number.isInteger(value))fail('数值无效');
    if(rule.minimum!==undefined&&value<rule.minimum||rule.maximum!==undefined&&value>rule.maximum||rule.exclusiveMaximum!==undefined&&value>=rule.exclusiveMaximum)fail('数值超出范围');
  }
}
module.exports=validateSchema;
